package com.example.discussions.service;import com.example.discussions.exception.ApiException;import com.example.discussions.model.User;import com.example.discussions.repository.UserRepository;import org.springframework.http.HttpStatus;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import java.util.Optional;@Service public class CurrentUser{private final UserRepository users;public CurrentUser(UserRepository users){this.users=users;}public Optional<User> optional(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null||!a.isAuthenticated()?Optional.empty():users.findByUsernameIgnoreCase(a.getName());}public User required(){return optional().orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Требуется вход"));}public void ownerOrAdmin(User author){var u=required();if(!u.id.equals(author.id)&&u.role!=User.Role.ADMIN)throw ApiException.forbidden();}}
